def choose_move(observation):
    def g(obj, key, default=None):
        try:
            return obj.get(key, default)
        except Exception:
            return default

    def is_num(v):
        return isinstance(v, (int, float)) and not isinstance(v, bool)

    def to_xy(v):
        if isinstance(v, (list, tuple)) and len(v) >= 2 and is_num(v[0]) and is_num(v[1]):
            return [int(v[0]), int(v[1])]
        if isinstance(v, dict):
            for ax, ay in (("x", "y"), ("col", "row"), ("i", "j")):
                if ax in v and ay in v and is_num(v[ax]) and is_num(v[ay]):
                    return [int(v[ax]), int(v[ay])]
        return None

    def extract_points(obj, keys):
        pts = []
        for k in keys:
            val = g(obj, k, None)
            if val is None:
                continue
            if isinstance(val, dict):
                xy = to_xy(val)
                if xy is not None:
                    pts.append(xy)
                else:
                    for subk in ("items", "cells", "positions", "points", "entities"):
                        sub = g(val, subk, None)
                        if isinstance(sub, list):
                            pts.extend(extract_points({"x": 0}, [subk]))
            elif isinstance(val, list):
                for it in val:
                    xy = to_xy(it)
                    if xy is not None:
                        pts.append(xy)
                    elif isinstance(it, dict):
                        xy = to_xy(it)
                        if xy is not None:
                            pts.append(xy)
        return pts

    def nearest_dist(p, pts):
        if not pts:
            return None
        best = None
        for q in pts:
            d = abs(p[0] - q[0]) + abs(p[1] - q[1])
            if best is None or d < best:
                best = d
        return best

    def clamp_move(dx, dy):
        if dx < -1:
            dx = -1
        elif dx > 1:
            dx = 1
        if dy < -1:
            dy = -1
        elif dy > 1:
            dy = 1
        return [dx, dy]

    obs = observation if isinstance(observation, dict) else {}
    me = None
    for mk in ("self", "agent", "player", "me", "unit", "avatar"):
        me = g(obs, mk, None)
        if me is not None:
            break
    if me is None:
        me = obs

    pos = None
    for pk in ("pos", "position", "loc", "location", "xy", "coord"):
        pos = to_xy(g(me, pk, None))
        if pos is not None:
            break
    if pos is None:
        for pk in ("x", "y"):
            pass
        x = g(me, "x", None)
        y = g(me, "y", None)
        if is_num(x) and is_num(y):
            pos = [int(x), int(y)]
    if pos is None:
        return [0, 0]

    role_text = ""
    for rk in ("role", "mode", "type", "team", "state", "status", "name"):
        rv = g(obs, rk, None)
        if rv is not None:
            role_text += " " + str(rv).lower()
        rv = g(me, rk, None)
        if rv is not None:
            role_text += " " + str(rv).lower()

    resources = extract_points(obs, ("resources", "resource", "food", "items", "pellets", "targets", "goal", "goals", "collectibles"))
    enemies = extract_points(obs, ("enemies", "enemy", "opponents", "opponent", "agents", "units", "players"))
    territory = extract_points(obs, ("territory", "cells", "tiles", "frontier", "unclaimed", "neutral", "capture_points"))

    size = g(obs, "size", None)
    width = g(obs, "width", None)
    height = g(obs, "height", None)
    center = None
    if isinstance(size, (list, tuple)) and len(size) >= 2 and is_num(size[0]) and is_num(size[1]):
        center = [int(size[0] // 2), int(size[1] // 2)]
    elif is_num(width) and is_num(height):
        center = [int(width // 2), int(height // 2)]

    pursue = ("hunter" in role_text) or ("predator" in role_text) or ("chaser" in role_text) or ("pursuer" in role_text)
    evade = ("prey" in role_text) or ("runner" in role_text) or ("evader" in role_text) or ("flee" in role_text)

    candidates = [[dx, dy] for dx in (-1, 0, 1) for dy in (-1, 0, 1)]
    best_move = [0, 0]
    best_score = None

    for dx, dy in candidates:
        nx = pos[0] + dx
        ny = pos[1] + dy
        score = 0

        if resources:
            d = nearest_dist([nx, ny], resources)
            if d is not None:
                score -= 6 * d

        if enemies:
            d = nearest_dist([nx, ny], enemies)
            if d is not None:
                if evade:
                    score += 8 * d
                elif pursue:
                    score -= 3 * d
                else:
                    if d <= 2:
                        score += 5 * d
                    else:
                        score -= d

        if territory:
            d = nearest_dist([nx, ny], territory)
            if d is not None:
                score -= 2 * d

        if center is not None and not resources and not enemies:
            score -= abs(nx - center[0]) + abs(ny - center[1])

        if dx == 0 and dy == 0:
            score -= 0.1

        if best_score is None or score > best_score:
            best_score = score
            best_move = [dx, dy]

    return clamp_move(best_move[0], best_move[1])

